def count_islands(grid: list[str]) -> int:
    seen = set()
    count = 0
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == "1" and (r, c) not in seen:
                count += 1
                stack = [(r, c)]
                while stack:
                    i, j = stack.pop()
                    if (i, j) in seen or not (0 <= i < len(grid) and 0 <= j < len(grid[0])):
                        continue
                    if grid[i][j] != "1":
                        continue
                    seen.add((i, j))
                    stack.extend([(i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)])
    return count
```

Each unvisited land cell starts a new island, and the stack flood-fills its whole component.

