def caesar(s: str, k: int) -> str:
    out = []
    for c in s:
        if c.islower():
            out.append(chr(ord('a') + (ord(c) - ord('a') + k) % 26))
        elif c.isupper():
            out.append(chr(ord('A') + (ord(c) - ord('A') + k) % 26))
        else:
            out.append(c)
    return ''.join(out)
```

Python's modulo is non-negative for a positive modulus, so negative k and k > 26 both work without extra handling.
